def svg(nome: str, tamanho: int = 18, classe: str = "") -> str:
    """HTML de um ícone Lucide (decorativo: ``aria-hidden``). Nome desconhecido gera um círculo neutro."""
    corpo = _ICONES.get(nome, '<circle cx="12" cy="12" r="9"/>')
    extra = f" {classe}" if classe else ""
    return (
        f'<svg class="ml-icone{extra}" xmlns="http://www.w3.org/2000/svg" width="{tamanho}" height="{tamanho}" '
        f'viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" '
        f'stroke-linejoin="round" aria-hidden="true" focusable="false">{corpo}</svg>'
    )


def existe(nome: str) -> bool:
    return nome in _ICONES
